DEFAULT_TIMEOUT = 30.0
DEFAULT_USER_AGENT = f"Kimi AgentGW PySDK/{__version__}"

API_KEY_ENV_VAR = "KIMI_API_KEY"
BASE_URL_ENV_VAR = "KIMI_BASE_URL"
CHAT_ID_ENV_VAR = "KIMI_CHAT_ID"
SESSION_ID_ENV_VAR = "KIMI_SESSION_ID"
THREAD_ID_ENV_VAR = "KIMI_THREAD_ID"
EVENT_ID_ENV_VAR = "KIMI_EVENT_ID"
CONFIG_FILE = Path("~/.kimi/agent-gw.json")  # 用户家目录下的固定路径


def _load_config_file() -> Dict[str, Any]:
    """读 ``~/.kimi/agent-gw.json``，文件不存在返回 ``{}``。

    JSON 必须是 ``{"api_key": "...", "base_url": "..."}`` 形式的对象，否则抛
    ``ValueError`` —— 这是配置错误，不该静默吃掉。
    """
    path = CONFIG_FILE.expanduser()
    if not path.is_file():
        return {}
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as e:
        raise ValueError(
            f"agent-gw config file {path} exists but could not be read: {e}"
        ) from e
    try:
        data = _json.loads(text)
    except _json.JSONDecodeError as e:
        raise ValueError(
            f"agent-gw config file {path} is not valid JSON: {e}"
        ) from e
    if not isinstance(data, dict):
        raise ValueError(
            f"agent-gw config file {path} must be a JSON object, got {type(data).__name__}"
        )
    return data


def _cfg_str(cfg: Mapping[str, Any], *keys: str) -> Optional[str]:
    """从 ``cfg`` 取首个非空字符串字段（自动 strip），都没值返回 ``None``。"""
    for key in keys:
        v = cfg.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return None


def _filename_from_content_disposition(header: str) -> Optional[str]:
    """从 ``Content-Disposition`` 头解析文件名（含 RFC 2231 ``filename*`` 解码）。

    只保留裸文件名，丢弃任何目录成分，防路径穿越。
    """
    if not header:
        return None
    msg = _EmailMessage()
    msg["Content-Disposition"] = header
    name = msg.get_filename()
    if not name:
        return None
    return Path(name).name or None


def _resolve_api_key(explicit: Optional[str], cfg: Mapping[str, Any]) -> str:
    """``显式参数 > KIMI_API_KEY env > JSON 配置 > 报错``"""
    if explicit:
        return explicit
    env = os.environ.get(API_KEY_ENV_VAR)
    if env and env.strip():
        return env.strip()
    file_val = _cfg_str(cfg, "api_key")
    if file_val:
        return file_val
    raise ValueError(
        "agent-gw API key not provided. Supply it via the api_key= argument, "
        f"the {API_KEY_ENV_VAR} env var, or put it in {CONFIG_FILE} as "
        '{"api_key": "sk-..."}.'
    )


def _resolve_base_url(explicit: Optional[str], cfg: Mapping[str, Any]) -> str:
    """``显式参数 > KIMI_BASE_URL env > JSON 配置 ``base_url`` > DEFAULT_BASE_URL``"""
    if explicit:
        return explicit
    env = os.environ.get(BASE_URL_ENV_VAR)
    if env and env.strip():
        return env.strip()
    file_val = _cfg_str(cfg, "base_url")
    if file_val:
        return file_val
    return DEFAULT_BASE_URL


def _resolve_kimi_chat_id(explicit: Optional[str], cfg: Mapping[str, Any]) -> Optional[str]:
    """``显式参数 > KIMI_CHAT_ID env > JSON 配置 ``kimi_chat_id`` > None``"""
    if explicit and explicit.strip():
        return explicit.strip()
    env = os.environ.get(CHAT_ID_ENV_VAR)
    if env and env.strip():
        return env.strip()
    return _cfg_str(cfg, "kimi_chat_id")


def _resolve_kimi_session_id(explicit: Optional[str], cfg: Mapping[str, Any]) -> Optional[str]:
    """``显式参数 > KIMI_SESSION_ID env > JSON 配置 ``kimi_session_id`` > None``"""
    if explicit and explicit.strip():
        return explicit.strip()
    env = os.environ.get(SESSION_ID_ENV_VAR)
    if env and env.strip():
        return env.strip()
    return _cfg_str(cfg, "kimi_session_id")


def _env_header(name: str) -> Optional[str]:
    """读取 per-exec 注入的环境变量（``KIMI_THREAD_ID`` / ``KIMI_EVENT_ID``），
    空白视为未设置。"""
    v = os.environ.get(name)
    if v and v.strip():
        return v.strip()
    return None


# 插件脚本的沙箱挂载前缀：loopy 与 darkmatter 两套布局。
PLUGIN_PATH_PREFIXES = ("/mnt/agents/plugins/", "/app/.agents/plugins/")


def _infer_plugin_name() -> Optional[str]:
    """从入口脚本路径推断插件名：``__main__.__file__`` 优先、``sys.argv[0]``
    回退；路径落在插件挂载前缀下时取前缀后的第一段目录名。"""
    candidates = []
    main_file = getattr(sys.modules.get("__main__"), "__file__", None)
    if main_file:
        candidates.append(main_file)
    if sys.argv and sys.argv[0]:
        candidates.append(sys.argv[0])
    for path in candidates:
        p = os.path.abspath(path)
        for prefix in PLUGIN_PATH_PREFIXES:
            if p.startswith(prefix):
                name = p[len(prefix):].split("/", 1)[0]
                if name:
                    return name
    return None


def _strip_tool_suffix(url: str) -> str:
    """为兼容已有 ``kimiPluginBaseUrl`` 配置，同时接受
    ``https://host`` 和 ``https://host/v1/tools`` 两种写法。"""
    url = url.rstrip("/")
    for suffix in ("/v1/tools", "/v1"):
        if url.endswith(suffix):
            return url[: -len(suffix)]
    return url


class ToolResponse:
    """``/v1/tools`` 返回信封的包装。

    agent-gw 返回信封结构::

        {
          "is_success": bool,
          "error": "...",
          "result": {"user": [{"text": "<内层 JSON 字符串>"}]}
        }
    """

    __slots__ = ("raw",)

    def __init__(self, raw: Any):
        # 大多数 method 返回 ``{"is_success": ..., "result": ...}`` 信封；
        # 但有的 method（如 ``get_data_source_desc``）直接返回 plain string，
        # 这里把非字典的响应包装成一个等价的成功信封，保持调用方代码一致。
        if isinstance(raw, Mapping):
            self.raw: Dict[str, Any] = dict(raw)
        elif isinstance(raw, str):
            self.raw = {"is_success": True, "result": {"user": [{"text": raw}]}}
        else:
            self.raw = {
                "is_success": True,
                "result": {"user": [{"text": _json.dumps(raw, ensure_ascii=False)}]},
            }

    @property
    def is_success(self) -> bool:
        if "is_success" in self.raw:
            return bool(self.raw.get("is_success"))
        # 无信封字段的响应（媒体生成 / 图搜返回原始 proto JSON）：HTTP 已 200，
        # 没有显式 error 即视为成功。
        return not self.raw.get("error")

    @property
    def error(self) -> str:
        err = self.raw.get("error", "")
        return err if isinstance(err, str) else str(err)

    @property
    def is_rate_limited(self) -> bool:
        if self.is_success:
            return False
        err = self.error.lower()
        return "429" in err or "rate" in err or "limit" in err

    @property
    def text(self) -> str:
        """首条用户文本（即内层 JSON 字符串原文）。"""
        users = self.raw.get("result", {}).get("user", [])
        if users and isinstance(users[0], Mapping):
            return users[0].get("text", "") or ""
        return ""

    def json(self) -> Any:
        """把 :attr:`text` 解析为 JSON。

        - 数据源信封：返回内层 ``result.user[0].text`` 解析后的对象。
        - 媒体生成 / 图搜：响应本身就是原始 JSON（无 ``result.user`` 信封），
          直接返回整个响应体 :attr:`raw`。
        """
        text = self.text
        if text:
            return _json.loads(text)
        if "result" not in self.raw:
            return self.raw
        return None

    def raise_for_status(self) -> "ToolResponse":
        if not self.is_success:
            raise ToolError(self.error or "tool invocation failed", raw=self.raw)
        return self

    def __repr__(self) -> str:
        return f"ToolResponse(is_success={self.is_success}, error={self.error!r})"


class ToolsAPI:
    """``POST /v1/tools`` 的封装。"""

    def __init__(self, client: "AgentGwClient"):
        self._client = client

    def invoke(
        self,
        method: str,
        params: Optional[Mapping[str, Any]] = None,
        *,
        timeout: Optional[float] = None,
    ) -> ToolResponse:
        body = {"method": method, "params": dict(params or {})}
        raw = self._client._post_json("/v1/tools", body, timeout=timeout)
        return ToolResponse(raw)

    # ── Typed convenience helpers ──────────────────────────────────────────
    def stock_realtime_price(
        self,
        ticker: str,
        *,
        time: str,
        type: str = "realtime_price",
        file_path: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> ToolResponse:
        """调用 ``get_stock_realtime_price``。

        参数:
            ticker:    股票代码；批量时用逗号分隔，如 ``"600519.SH"`` 或
                       ``"600519.SH,000001.SZ"``。美股需带 ``.US`` 后缀，
                       例如 ``"AAPL.US"``。
            time:      时间字符串 ``"YYYY-MM-DD HH:MM:SS"``。美股 iFind 期望
                       美东时间（ET），其余市场传北京时间。
            type:      ``"realtime_price"``（默认）或 ``"realtime_tech"``。
            file_path: 可选的 iFind 临时文件路径，例如 ``/tmp/foo.json``。
        """
        params: Dict[str, Any] = {"ticker": ticker, "time": time, "type": type}
        if file_path:
            params["file_path"] = file_path
        return self.invoke("get_stock_realtime_price", params, timeout=timeout)

    def nlp_tokenize(self, text: str, **opts: Any) -> ToolResponse:
        return self.invoke("nlp_tokenize", {"text": text, **opts})

    def nlp_normalize(self, text: str, **opts: Any) -> ToolResponse:
        return self.invoke("nlp_normalize", {"text": text, **opts})

    def nlp_shortkeys(self, text: str, **opts: Any) -> ToolResponse:
        return self.invoke("nlp_shortkeys", {"text": text, **opts})

    def nlp_embedding(self, texts: Union[str, List[str]], **opts: Any) -> ToolResponse:
        """调用 ``nlp_embedding``。

        服务端字段名为 ``texts``（数组），单串入参会自动包成单元素列表。
        """
        if isinstance(texts, str):
            texts = [texts]
        return self.invoke("nlp_embedding", {"texts": list(texts), **opts})

    def call_data_source_tool(self, params: Mapping[str, Any]) -> ToolResponse:
        return self.invoke("call_data_source_tool", params)

    def get_data_source_desc(self, params: Mapping[str, Any]) -> ToolResponse:
        return self.invoke("get_data_source_desc", params)

    # ── 媒体生成 / 图搜 ────────────────────────────────────────────────────
    # 这些 method 的素材与产物均为文件 URL：素材可先通过 agent-gw 的
    # ``POST /v1/storage`` 上传拿到 ``signed_url`` 再作为 reference_*_urls 传入；
    # 产物以 URL 形式在响应中返回。参数按对应 proto 字段透传，未列出的字段可用
    # ``**opts`` 传入。

    def generate_image(
        self,
        description: str,
        *,
        ratio: Optional[str] = None,
        resolution: Optional[str] = None,
        background: Optional[str] = None,
        reference_image_urls: Optional[List[str]] = None,
        timeout: Optional[float] = 120.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``generate_image``（生图）。

        参数对应 ``agent.media.v1.GenerateImageRequest``：``ratio`` 如 ``"1:1"``，
        ``resolution`` 如 ``"1K"``，``background`` 如 ``"IMAGE_BACKGROUND_OPAQUE"``，
        ``reference_image_urls`` 为参考图的公网 URL 列表。
        """
        params: Dict[str, Any] = {"description": description, **opts}
        if ratio is not None:
            params["ratio"] = ratio
        if resolution is not None:
            params["resolution"] = resolution
        if background is not None:
            params["background"] = background
        if reference_image_urls is not None:
            params["reference_image_urls"] = list(reference_image_urls)
        return self.invoke("generate_image", params, timeout=timeout)

    def generate_sound_effects(
        self,
        description: str,
        *,
        duration_seconds: Optional[float] = None,
        timeout: Optional[float] = 120.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``generate_sound_effects``（生音效音频）。"""
        params: Dict[str, Any] = {"description": description, **opts}
        if duration_seconds is not None:
            params["duration_seconds"] = duration_seconds
        return self.invoke("generate_sound_effects", params, timeout=timeout)

    def generate_speech(
        self,
        text: str,
        *,
        voice_id: Optional[str] = None,
        timeout: Optional[float] = 120.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``generate_speech``（生人声音频）。"""
        params: Dict[str, Any] = {"text": text, **opts}
        if voice_id is not None:
            params["voice_id"] = voice_id
        return self.invoke("generate_speech", params, timeout=timeout)

    def generate_video(
        self,
        description: str,
        *,
        ratio: Optional[str] = None,
        resolution: Optional[str] = None,
        duration_seconds: Optional[int] = None,
        reference_image_urls: Optional[List[str]] = None,
        reference_video_urls: Optional[List[str]] = None,
        reference_audio_urls: Optional[List[str]] = None,
        generate_audio: Optional[bool] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``generate_video``（生视频）。视频生成较慢，默认 timeout 放宽到 300s。"""
        params: Dict[str, Any] = {"description": description, **opts}
        if ratio is not None:
            params["ratio"] = ratio
        if resolution is not None:
            params["resolution"] = resolution
        if duration_seconds is not None:
            params["duration_seconds"] = duration_seconds
        if reference_image_urls is not None:
            params["reference_image_urls"] = list(reference_image_urls)
        if reference_video_urls is not None:
            params["reference_video_urls"] = list(reference_video_urls)
        if reference_audio_urls is not None:
            params["reference_audio_urls"] = list(reference_audio_urls)
        if generate_audio is not None:
            params["generate_audio"] = generate_audio
        return self.invoke("generate_video", params, timeout=timeout)

    def generate_3d_model(
        self,
        description: Optional[str] = None,
        *,
        image_url: Optional[str] = None,
        multiview: Optional[Mapping[str, str]] = None,
        version: Optional[str] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``generate_3d_model``（生 3D 模型，返回 GLB 模型与渲染预览图 URL）。

        参数对应 ``agent.media.v1.Generate3DModelRequest``：``description``（文生模型）、
        ``image_url``（图生模型，公网图片 URL）、``multiview``（多视角生模型，
        ``{"front_url": ..., "left_url": ..., "back_url": ..., "right_url": ...}``，
        front 必填且至少两个视角）三种输入必须且只能提供一种。
        3D 生成较慢，默认 timeout 放宽到 300s。
        """
        params: Dict[str, Any] = dict(opts)
        if description is not None:
            params["description"] = description
        if image_url is not None:
            params["image_url"] = image_url
        if multiview is not None:
            params["multiview"] = dict(multiview)
        if version is not None:
            params["version"] = version
        return self.invoke("generate_3d_model", params, timeout=timeout)

    def texture_3d_model(
        self,
        model_url: Optional[str] = None,
        *,
        task_id: Optional[str] = None,
        prompt: Optional[str] = None,
        style_image_url: Optional[str] = None,
        version: Optional[str] = None,
        model: Optional[str] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``texture_3d_model``（3D 模型贴图/重贴图）。

        参数对应 ``agent.media.v1.Texture3DModelRequest``：``model_url``（源模型公网
        URL，GLB/GLTF/FBX/OBJ/STL）与 ``task_id``（此前 3D 任务的 ID，直接复用其产物）
        必须且只能提供一种；``prompt`` 描述纹理风格，``style_image_url`` 为风格参考图
        （仅在 ``prompt`` 设置时生效）；``model`` 可覆盖上游贴图模型版本。
        默认 timeout 300s。
        """
        params: Dict[str, Any] = dict(opts)
        if model_url is not None:
            params["model_url"] = model_url
        if task_id is not None:
            params["task_id"] = task_id
        if prompt is not None:
            params["prompt"] = prompt
        if style_image_url is not None:
            params["style_image_url"] = style_image_url
        if version is not None:
            params["version"] = version
        if model is not None:
            params["model"] = model
        return self.invoke("texture_3d_model", params, timeout=timeout)

    def segment_3d_model(
        self,
        model_url: Optional[str] = None,
        *,
        task_id: Optional[str] = None,
        version: Optional[str] = None,
        model: Optional[str] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``segment_3d_model``（3D 模型语义网格分割）。

        参数对应 ``agent.media.v1.Segment3DModelRequest``：``model_url`` 与 ``task_id``
        必须且只能提供一种；返回的 ``task_id`` 可传给 :meth:`complete_3d_model`。
        默认 timeout 300s。
        """
        params: Dict[str, Any] = dict(opts)
        if model_url is not None:
            params["model_url"] = model_url
        if task_id is not None:
            params["task_id"] = task_id
        if version is not None:
            params["version"] = version
        if model is not None:
            params["model"] = model
        return self.invoke("segment_3d_model", params, timeout=timeout)

    def decimate_3d_model(
        self,
        model_url: Optional[str] = None,
        *,
        task_id: Optional[str] = None,
        face_limit: Optional[int] = None,
        version: Optional[str] = None,
        model: Optional[str] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``decimate_3d_model``（3D 模型减面/重拓扑）。

        参数对应 ``agent.media.v1.Decimate3DModelRequest``：``model_url`` 与 ``task_id``
        必须且只能提供一种；``face_limit`` 为目标面数，不填则上游自适应减面。
        默认 timeout 300s。
        """
        params: Dict[str, Any] = dict(opts)
        if model_url is not None:
            params["model_url"] = model_url
        if task_id is not None:
            params["task_id"] = task_id
        if face_limit is not None:
            params["face_limit"] = face_limit
        if version is not None:
            params["version"] = version
        if model is not None:
            params["model"] = model
        return self.invoke("decimate_3d_model", params, timeout=timeout)

    def complete_3d_model(
        self,
        task_id: str,
        *,
        part_names: Optional[List[str]] = None,
        completion_mode: Optional[str] = None,
        version: Optional[str] = None,
        model: Optional[str] = None,
        timeout: Optional[float] = 300.0,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``complete_3d_model``（3D 分割部件网格补全）。

        参数对应 ``agent.media.v1.Complete3DModelRequest``：``task_id`` 为此前
        ``segment_3d_model`` 任务的 ID；``part_names`` 指定要补全的部件名（不填补全部）；
        ``completion_mode`` 为 ``"ai_completion"``（默认，AI 生成几何）或
        ``"quick_cap"``（快速边界封口）。默认 timeout 300s。
        """
        params: Dict[str, Any] = {"task_id": task_id, **opts}
        if part_names is not None:
            params["part_names"] = list(part_names)
        if completion_mode is not None:
            params["completion_mode"] = completion_mode
        if version is not None:
            params["version"] = version
        if model is not None:
            params["model"] = model
        return self.invoke("complete_3d_model", params, timeout=timeout)

    def search_image(
        self,
        keywords: Optional[Union[str, List[str]]] = None,
        *,
        page_size: Optional[int] = None,
        timeout: Optional[float] = None,
        **opts: Any,
    ) -> ToolResponse:
        """调用 ``search_image``（图搜），透传到 ``search.v3.SearchImageRequest``。

        其余字段（``scene`` / ``engines`` / ``page_token`` 等）可用 ``**opts`` 传入。
        """
        params: Dict[str, Any] = dict(opts)
        if keywords is not None:
            if isinstance(keywords, str):
                keywords = [keywords]
            params["keywords"] = list(keywords)
        if page_size is not None:
            params["page_size"] = page_size
        return self.invoke("search_image", params, timeout=timeout)

    # ── Design Asset ───────────────────────────────────────────────────────

    def search_design_asset(
        self,
        query: str,
        *,
        top_k: Optional[int] = None,
        type: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> ToolResponse:
        """调用 ``search_design_asset``（Design Asset 搜索，免费）。

        ``query`` 匹配资产 name / description / keywords（文本 + 向量混合检索），
        ≤512 字符；``top_k`` 1~10，默认 5（越界由服务端按边界截断）；
        ``type`` 可选资产类型过滤（服务端缺省 3d），不传表示不过滤。

        响应无数据源信封，``ToolResponse.json()`` 直接返回整个响应体::

            {"results": [{"uuid", "name", "type", "description"}, ...]}

        结果只含元数据；``uuid`` 是 :meth:`fetch_design_asset` 取件的唯一
        凭据，每次成功取件计费一次（``fetch_design_asset``）。
        """
        params: Dict[str, Any] = {"query": query}
        if top_k is not None:
            params["top_k"] = top_k
        if type is not None:
            params["type"] = type
        return self.invoke("search_design_asset", params, timeout=timeout)

    def fetch_design_asset(
        self,
        uuid: str,
        dest_dir: Union[str, Path] = ".",
        *,
        timeout: Optional[float] = 120.0,
    ) -> Path:
        """按 uuid 取回资产 zip（``fetch_design_asset``，每次成功取件计费一次），
        返回保存路径。

        走 ``POST /v1/tools`` 通用鉴权与计费链路；成功时响应为 zip 裸字节流，
        保存文件名取自响应的 ``Content-Disposition``（即资产名），取不到时
        退回 ``asset.zip``。

        zip 为**平铺结构**（无顶层目录），解压务必指定目录，例如
        ``unzip -o asset.zip -d <asset_name>/``；包内含生成代码
        （.py / .mjs / .glsl）、烘焙产物（.blend / .glb）与 preview.png。
        """
        if not uuid or not uuid.strip():
            raise ValueError("uuid must not be empty")
        dest = Path(dest_dir).expanduser()
        dest.mkdir(parents=True, exist_ok=True)
        body = {"method": "fetch_design_asset", "params": {"uuid": uuid.strip()}}
        # _request 已内置鉴权头、超时/传输异常封装与 >=400 错误映射。
        resp = self._client._request("POST", "/v1/tools", json=body, stream=True, timeout=timeout)
        try:
            filename = (
                _filename_from_content_disposition(resp.headers.get("Content-Disposition", ""))
                or "asset.zip"
            )
            out = dest / filename
            with out.open("wb") as fh:
                for chunk in resp.iter_content(chunk_size=64 * 1024):
                    if chunk:
                        fh.write(chunk)
        finally:
            resp.close()
        return out


# 任务状态（查询接口在产物就绪前返回 processing）
TASK_STATUS_PENDING = "pending"
TASK_STATUS_PROCESSING = "processing"
TASK_STATUS_SUCCEEDED = "succeeded"
TASK_STATUS_FAILED = "failed"
TASK_TERMINAL_STATUSES = frozenset({TASK_STATUS_SUCCEEDED, TASK_STATUS_FAILED})


class TasksAPI:
    """``/v1/tasks`` 的两阶段异步任务接口：提交任务 + 查询任务。

    任务语义：提交（multipart 上传，``type`` 指定任务类型）返回 ``task_id``，
    服务端异步处理并**在任务完成时自行完成计费结算**（成功按实际时长扣费、
    失败全额退回），与客户端是否查询无关；查询是只读操作，不触发计费。

    当前支持的任务类型：
      - ``"asr"``：录音转写（音频文件，mp3/wav/m4a/ogg/flac，≤500MB）。
    """

    TYPE_ASR = "asr"

    def __init__(self, client: "AgentGwClient"):
        self._client = client

    def submit(
        self,
        task_type: str,
        file: Union[str, "os.PathLike[str]", bytes, bytearray, BinaryIO, Tuple[Any, ...]],
        *,
        filename: Optional[str] = None,
        content_type: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """调用 ``POST /v1/tasks`` —— multipart 提交异步任务。

        参数:
            task_type:    任务类型，当前为 ``"asr"``。
            file:         任务输入文件，形态同 :meth:`AgentGwClient.upload_file`
                          （路径 / 字节 / 类文件对象 / 元组）。
            filename:     覆盖文件名（asr 按扩展名校验音频格式）。
            content_type: 显式 MIME 类型；不传按后缀猜测。
            timeout:      本次请求超时（秒）。大文件上传建议调大。

        返回服务端 JSON：``{task_id, type, status, created_at}``。
        """
        file_tuple = _build_file_tuple(file, filename=filename, content_type=content_type)
        return self._client._post_multipart(
            "/v1/tasks",
            files={"file": file_tuple},
            data={"type": task_type},
            timeout=timeout,
        )

    def submit_asr(
        self,
        file: Union[str, "os.PathLike[str]", bytes, bytearray, BinaryIO, Tuple[Any, ...]],
        *,
        filename: Optional[str] = None,
        content_type: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """``submit(type="asr")`` 的便捷写法：提交录音转写任务。

        支持 mp3 / wav / m4a / ogg / flac，单文件 ≤500MB、时长 ≤5 小时。
        返回 ``{task_id, type, status, created_at}``，初始 ``status="pending"``。
        """
        return self.submit(
            self.TYPE_ASR, file, filename=filename, content_type=content_type, timeout=timeout
        )

    def wait_asr(
        self,
        task_id: str,
        *,
        interval: float = 5.0,
        timeout: float = 600.0,
        on_status: Optional[Any] = None,
    ) -> "ASRTaskResult":
        """轮询 asr 任务到终态并返回类型化结果 :class:`ASRTaskResult`。"""
        body = self.wait(task_id, interval=interval, timeout=timeout, on_status=on_status)
        return ASRTaskResult(self._client, body)

    def transcribe(
        self,
        file: Union[str, "os.PathLike[str]", bytes, bytearray, BinaryIO, Tuple[Any, ...]],
        *,
        filename: Optional[str] = None,
        content_type: Optional[str] = None,
        interval: float = 5.0,
        timeout: float = 600.0,
        on_status: Optional[Any] = None,
    ) -> "ASRTaskResult":
        """一把梭：提交录音转写任务并等待完成，返回 :class:`ASRTaskResult`。

        等价于 ``submit_asr`` + ``wait_asr``。转写失败**不抛异常**（失败是正常
        业务终态，检查返回值的 ``is_success`` / ``error``，或调
        ``raise_for_status()``）；超时抛 :class:`APIError`。

        用法::

            result = client.tasks.transcribe("meeting.mp3", timeout=1800)
            if result.is_success:
                print(result.duration_ms, result.fetch_text())
        """
        task = self.submit_asr(file, filename=filename, content_type=content_type, timeout=timeout)
        task_id = (task or {}).get("task_id")
        if not task_id:
            raise APIError(f"submit asr task returned no task_id: {task}", status_code=0, body=task)
        return self.wait_asr(task_id, interval=interval, timeout=timeout, on_status=on_status)

    def get(self, task_id: str, *, timeout: Optional[float] = None) -> Any:
        """调用 ``GET /v1/tasks/{task_id}`` —— 查询任务状态与结果（只读，不计费）。

        返回服务端 JSON：``{task_id, type, status, result?, error?, created_at,
        settled_at?}``。``status`` 为 ``pending`` / ``processing`` / ``succeeded`` /
        ``failed``；asr 成功时 ``result`` 含 ``text_url``（纯文本逐字稿）、
        ``utterances_url``（说话人分段 JSON）、``duration_ms``（音频实测时长，
        计费计量值）。任务不存在（或不属于当前用户、或终态记录已过期）时抛
        :class:`NotFoundError`。
        """
        return self._client._get_json(f"/v1/tasks/{task_id}", timeout=timeout)

    def wait(
        self,
        task_id: str,
        *,
        interval: float = 5.0,
        timeout: float = 600.0,
        on_status: Optional[Any] = None,
    ) -> Any:
        """轮询 :meth:`get` 直到任务到达终态（``succeeded`` / ``failed``）。

        参数:
            interval:  轮询间隔（秒），默认 5s。
            timeout:   最长等待（秒），默认 600s；超时抛 :class:`APIError`。
            on_status: 可选回调 ``fn(status: str, body: dict)``，每轮调用一次，
                       便于打印进度。

        返回终态的完整响应（同 :meth:`get`）。``failed`` 时**不抛异常**——
        失败是正常业务终态，由调用方读 ``status`` / ``error`` 判断。
        """
        deadline = time.monotonic() + timeout
        while True:
            body = self.get(task_id)
            status = (body or {}).get("status", "unknown") if isinstance(body, Mapping) else "unknown"
            if on_status is not None:
                on_status(status, body)
            if status in TASK_TERMINAL_STATUSES:
                return body
            if time.monotonic() >= deadline:
                raise APIError(
                    f"task {task_id} not terminal after {timeout}s (last status: {status})",
                    status_code=0,
                    body=body,
                )
            time.sleep(interval)


# ── ASR 任务类型化结果 ──────────────────────────────────────────────────────
class TaskWarning:
    """任务成功但结果有瑕疵时的机器可读警告（``result.warnings`` 数组元素）。

    当前唯一 code 为 ``audio_truncated``：音频文件疑似截断，转写仅覆盖
    可解码部分（任务仍为成功、按实际解码时长计费）。调用方按 ``code``
    做 i18n 翻译展示；``message`` 为英文兜底文案（不内嵌数值）。
    实际解码时长即 :attr:`ASRTaskResult.duration_ms`。
    """

    def __init__(self, data: Mapping[str, Any]):
        self.code: str = data.get("code", "")
        self.message: str = data.get("message", "")
        self.declared_duration_ms: int = data.get("declared_duration_ms", 0)

    @property
    def is_truncated(self) -> bool:
        return self.code == "audio_truncated"

    def __repr__(self) -> str:
        return f"<TaskWarning code={self.code!r} declared={self.declared_duration_ms}>"


class ASRTaskResult:
    """asr（录音转写）任务的类型化结果，对标 :class:`ToolResponse` 的角色。

    由 :meth:`TasksAPI.wait_asr` / :meth:`TasksAPI.transcribe` 返回。
    签名 URL 每次 :meth:`TasksAPI.get` 都会重签（测试环境单条约 5 天有效），
    :meth:`fetch_text` / :meth:`fetch_utterances` 下载时**不带 apikey、不经网关**
    （kimifs 307 → 对象存储）。
    """

    def __init__(self, client: "AgentGwClient", body: Mapping[str, Any]):
        self._client = client
        self.raw: Mapping[str, Any] = body
        self.task_id: str = body.get("task_id", "")
        self.status: str = body.get("status", "")
        self.error: str = body.get("error", "")
        self.created_at: int = body.get("created_at", 0)
        self.settled_at: int = body.get("settled_at", 0)
        result = body.get("result") or {}
        self.text_url: Optional[str] = result.get("text_url")
        self.utterances_url: Optional[str] = result.get("utterances_url")
        self.duration_ms: int = result.get("duration_ms", 0)
        self.warnings: List[TaskWarning] = [
            TaskWarning(w) for w in (result.get("warnings") or []) if isinstance(w, Mapping)
        ]

    @property
    def is_success(self) -> bool:
        return self.status == TASK_STATUS_SUCCEEDED

    @property
    def is_truncated(self) -> bool:
        """音频疑似截断（成功但只转写了可解码部分），此时 :attr:`warnings` 含 ``audio_truncated``。"""
        return any(w.is_truncated for w in self.warnings)

    def _fetch(self, url: Optional[str], timeout: Optional[float]) -> requests.Response:
        if not url:
            raise APIError(
                f"task {self.task_id} has no result url (status: {self.status})",
                status_code=0,
                body=self.raw,
            )
        try:
            resp = self._client._session.request(
                "GET",
                url,
                timeout=timeout if timeout is not None else self._client.timeout,
                allow_redirects=True,
            )
        except requests.exceptions.RequestException as e:
            raise TransportError(f"download error for task {self.task_id}: {e}") from e
        if resp.status_code >= 400:
            raise APIError(
                f"download failed: HTTP {resp.status_code}",
                status_code=resp.status_code,
                body=resp.text,
            )
        return resp

    def fetch_text(self, *, timeout: Optional[float] = None) -> str:
        """下载纯文本逐字稿（text_url 指向的内容）。"""
        return self._fetch(self.text_url, timeout).text

    def fetch_utterances(self, *, timeout: Optional[float] = None) -> List[Dict[str, Any]]:
        """下载说话人分段 JSON：[{text, start_time, end_time, words, additions:{speaker}}]。"""
        return self._fetch(self.utterances_url, timeout).json()

    def raise_for_status(self) -> "ASRTaskResult":
        if not self.is_success:
            raise ToolError(f"asr task {self.task_id} not succeeded: {self.status} {self.error}")
        return self

    def __repr__(self) -> str:
        return f"<ASRTaskResult task_id={self.task_id!r} status={self.status!r} duration_ms={self.duration_ms}>"


class AgentGwClient:
    """Kimi agent-gw 的同步客户端。

    ``api_key`` / ``base_url`` / ``kimi_chat_id`` 都按下面这套优先级解析（**取第一个非空**）：

        1. 此处显式传入的参数
        2. 环境变量（``KIMI_API_KEY`` / ``KIMI_BASE_URL`` / ``KIMI_CHAT_ID``）
        3. JSON 配置文件 ``~/.kimi/agent-gw.json`` 中的对应字段
        4. 兜底：``api_key`` 没有时抛 ``ValueError``；``base_url`` 退到
           ``DEFAULT_BASE_URL``；``kimi_chat_id`` 没有就不发 ``X-Kimi-Chat-Id`` 头

    JSON 文件示例::

        {
          "api_key":      "sk-...",
          "base_url":     "https://agent-gw-dev.dev.kimi.team/coding",
          "kimi_chat_id": "可选；存在则所有请求都会带 X-Kimi-Chat-Id 头",
          "kimi_session_id": "可选；存在则所有请求都会带 X-Kimi-Session-Id 头"
        }

    其它参数:
        timeout:    默认请求超时（秒）。
        skill:      可选；写入 ``X-Kimi-Skill`` 请求头。
        plugin:     可选；写入 ``X-Kimi-Plugin`` 请求头（用量归因）。不传时
                      按入口脚本路径推断：``__main__.__file__`` / ``sys.argv[0]``
                      落在 ``/mnt/agents/plugins/<name>/`` 或
                      ``/app/.agents/plugins/<name>/`` 下即自动携带 ``<name>``。
        kimi_chat_id: 可选；写入 ``X-Kimi-Chat-Id`` 请求头。不传时回落到
                      ``KIMI_CHAT_ID`` 环境变量，再不行回落到 JSON 配置文件
                      中的 ``kimi_chat_id`` 字段。
        kimi_session_id: 可选；写入 ``X-Kimi-Session-Id`` 请求头（用量归因，
                      沙箱环境由平台写进 JSON 配置的 ``kimi_session_id``
                      字段）。解析顺序同 ``kimi_chat_id``：显式参数 >
                      ``KIMI_SESSION_ID`` env > JSON 配置。

    此外每次请求会读取执行进程环境变量 ``KIMI_THREAD_ID`` / ``KIMI_EVENT_ID``
    （平台在每次沙箱 exec 时注入），存在则分别写入 ``X-Kimi-Thread-Id`` /
    ``X-Kimi-Event-Id`` 请求头，用于把 gw 调用归因回发起它的 Thread 与
    tool call。
        user_agent: 覆盖默认 User-Agent；不传时使用
                    ``"Kimi AgentGW PySDK/<version>"``。
        session:    传入自定义的 :class:`requests.Session`（连接池、
                    重试适配器、Mock 等场景）。
        extra_headers: 附加请求头，每次请求都会带上。
    """

    def __init__(
        self,
        api_key: Optional[str] = None,
        *,
        base_url: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        skill: Optional[str] = None,
        plugin: Optional[str] = None,
        kimi_chat_id: Optional[str] = None,
        kimi_session_id: Optional[str] = None,
        user_agent: Optional[str] = None,
        session: Optional[requests.Session] = None,
        extra_headers: Optional[Mapping[str, str]] = None,
    ):
        cfg = _load_config_file()
        self.api_key = _resolve_api_key(api_key, cfg)
        self.base_url = _strip_tool_suffix(_resolve_base_url(base_url, cfg))
        self.timeout = float(timeout)
        self.skill = skill
        self.plugin = (plugin.strip() if plugin and plugin.strip() else None) or _infer_plugin_name()
        self.kimi_chat_id = _resolve_kimi_chat_id(kimi_chat_id, cfg)
        self.kimi_session_id = _resolve_kimi_session_id(kimi_session_id, cfg)
        self.user_agent = user_agent or DEFAULT_USER_AGENT
        self._extra_headers = dict(extra_headers or {})
        self._session = session or requests.Session()
        self.tools = ToolsAPI(self)
        self.tasks = TasksAPI(self)

    # ── lifecycle ──────────────────────────────────────────────────────────
    def close(self) -> None:
        self._session.close()

    def __enter__(self) -> "AgentGwClient":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    # ── HTTP transport ─────────────────────────────────────────────────────
    def _headers(self, extra: Optional[Mapping[str, str]] = None) -> Dict[str, str]:
        h = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": self.user_agent,
        }
        if self.skill:
            h["X-Kimi-Skill"] = self.skill
        if self.plugin:
            h["X-Kimi-Plugin"] = self.plugin
        if self.kimi_chat_id:
            h["X-Kimi-Chat-Id"] = self.kimi_chat_id
        if self.kimi_session_id:
            h["X-Kimi-Session-Id"] = self.kimi_session_id
        thread_id = _env_header(THREAD_ID_ENV_VAR)
        if thread_id:
            h["X-Kimi-Thread-Id"] = thread_id
        event_id = _env_header(EVENT_ID_ENV_VAR)
        if event_id:
            h["X-Kimi-Event-Id"] = event_id
        if self._extra_headers:
            h.update(self._extra_headers)
        if extra:
            h.update(extra)
        return h

    def _request(
        self,
        method: str,
        path: str,
        *,
        json: Any = None,
        data: Any = None,
        files: Any = None,
        params: Optional[Mapping[str, Any]] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: Optional[float] = None,
        stream: bool = False,
    ) -> requests.Response:
        url = self.base_url + path if path.startswith("/") else f"{self.base_url}/{path}"
        h = self._headers(headers)
        if files is not None:
            # multipart: 必须让 requests 根据 files 自动生成 Content-Type 和 boundary
            h.pop("Content-Type", None)
        try:
            resp = self._session.request(
                method,
                url,
                json=json,
                data=data,
                files=files,
                params=params,
                headers=h,
                timeout=timeout if timeout is not None else self.timeout,
                stream=stream,
            )
        except requests.exceptions.Timeout as e:
            raise TransportError(f"Timeout calling {method} {path}: {e}") from e
        except requests.exceptions.RequestException as e:
            raise TransportError(f"Transport error calling {method} {path}: {e}") from e
        if resp.status_code >= 400:
            self._raise_for_status(resp)
        return resp

    def _post_json(
        self,
        path: str,
        body: Any,
        *,
        timeout: Optional[float] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Any:
        resp = self._request("POST", path, json=body, headers=headers, timeout=timeout)
        if resp.status_code == 204 or not resp.content:
            return None
        return resp.json()

    def _post_multipart(
        self,
        path: str,
        *,
        files: Mapping[str, Any],
        data: Optional[Mapping[str, Any]] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        resp = self._request("POST", path, files=files, data=data, timeout=timeout)
        if resp.status_code == 204 or not resp.content:
            return None
        return resp.json()

    def _get_json(
        self,
        path: str,
        *,
        params: Optional[Mapping[str, Any]] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        resp = self._request("GET", path, params=params, timeout=timeout)
        if resp.status_code == 204 or not resp.content:
            return None
        return resp.json()

    def _raise_for_status(self, resp: requests.Response) -> None:
        status = resp.status_code
        request_id = resp.headers.get("X-Request-ID") or resp.headers.get("x-request-id")
        body: Any
        try:
            body = resp.json()
        except ValueError:
            body = resp.text
        msg = _extract_error_message(body) or resp.reason or "request failed"
        kwargs = {"status_code": status, "body": body, "request_id": request_id}
        if status == 401:
            raise AuthenticationError(msg, **kwargs)
        if status == 402:
            raise PaymentRequiredError(msg, **kwargs)
        if status == 403:
            # ACL 策略拒绝（key 已识别但无端点权限）与额度耗尽分开归类，
            # 避免权限问题被误导向"额度/计费"方向排查。
            if _extract_error_code(body) == "api_key_path_forbidden":
                raise PermissionDeniedError(msg, **kwargs)
            raise QuotaExceededError(msg, **kwargs)
        if status == 404:
            raise NotFoundError(msg, **kwargs)
        if status == 429:
            retry_after_raw = resp.headers.get("Retry-After")
            try:
                retry_after = float(retry_after_raw) if retry_after_raw else None
            except ValueError:
                retry_after = None
            raise RateLimitError(msg, retry_after=retry_after, **kwargs)
        if status >= 500:
            raise ServerError(msg, **kwargs)
        raise APIError(msg, **kwargs)

    # ── high-level endpoints ──────────────────────────────────────────────
    def list_models(self, *, timeout: Optional[float] = None) -> Any:
        return self._get_json("/v1/models", timeout=timeout)

    def chat_completion(
        self,
        *,
        model: str,
        messages: List[Mapping[str, Any]],
        stream: bool = False,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Any:
        body: Dict[str, Any] = {"model": model, "messages": list(messages)}
        body.update(kwargs)
        if stream:
            body["stream"] = True
            return self._sse_iter("/v1/chat/completions", body, timeout=timeout)
        body["stream"] = False
        return self._post_json("/v1/chat/completions", body, timeout=timeout)

    def messages(
        self,
        *,
        model: str,
        messages: List[Mapping[str, Any]],
        max_tokens: int,
        stream: bool = False,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Any:
        body: Dict[str, Any] = {
            "model": model,
            "messages": list(messages),
            "max_tokens": max_tokens,
        }
        body.update(kwargs)
        if stream:
            body["stream"] = True
            return self._sse_iter("/v1/messages", body, timeout=timeout)
        body["stream"] = False
        return self._post_json("/v1/messages", body, timeout=timeout)

    def count_tokens(
        self,
        *,
        model: str,
        messages: List[Mapping[str, Any]],
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Any:
        body: Dict[str, Any] = {"model": model, "messages": list(messages)}
        body.update(kwargs)
        return self._post_json("/v1/messages/count_tokens", body, timeout=timeout)

    def embeddings(
        self,
        *,
        model: str,
        input: Union[str, List[str]],
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Any:
        body: Dict[str, Any] = {"model": model, "input": input}
        body.update(kwargs)
        return self._post_json("/v1/embeddings", body, timeout=timeout)

    def search(self, query: str, *, timeout: Optional[float] = None, **kwargs: Any) -> Any:
        """调用 ``POST /v1/search``。

        参数:
            query:    搜索词；服务端字段名为 ``text_query``。
            **kwargs: 可选透传，例如 ``timeout_seconds``、``enable_page_crawling``、
                      ``limit``（详见服务端 ``websearch.Request``）。

        返回值的 ``search_results`` 字段是结果列表。
        """
        body = {"text_query": query, **kwargs}
        return self._post_json("/v1/search", body, timeout=timeout)

    def fetch(
        self,
        url: str,
        *,
        as_markdown: bool = False,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Any:
        body = {"url": url, **kwargs}
        headers = {"Accept": "text/markdown"} if as_markdown else None
        resp = self._request("POST", "/v1/fetch", json=body, headers=headers, timeout=timeout)
        if as_markdown:
            return resp.text
        return resp.json()

    def upload_file(
        self,
        file: Union[str, "os.PathLike[str]", bytes, bytearray, BinaryIO, Tuple[Any, ...]],
        *,
        purpose: str = "file-extract",
        filename: Optional[str] = None,
        content_type: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """调用 ``POST /v1/files`` —— multipart 文件上传，agent-gw 透传到 OpenGW。

        服务端只暴露上传（POST）一个端点，不支持 LIST/GET/DELETE/CONTENT。

        参数:
            file:         待上传的文件，支持四种写法：
                          - ``str`` 或 ``pathlib.Path``：当作文件路径，自动以二进制方式读取；
                          - ``bytes`` / ``bytearray``：原始字节，需要配合 ``filename`` 才能
                            推断扩展名（不传则用 ``"upload"``）；
                          - 类文件对象（带 ``.read()``）：调用 ``read()`` 读完整内容；
                          - ``(filename, content[, content_type])`` 元组：直接透传给 requests。
            purpose:      OpenAI 风格的 ``purpose`` 字段，agent-gw 默认值是 ``"file-extract"``。
            filename:     覆盖文件名（多 part 表单里 ``filename=`` 段）。
            content_type: 显式指定 MIME 类型；不传时按文件名后缀猜测，猜不到落到
                          ``application/octet-stream``。
            timeout:      本次请求超时（秒），不传用 client 默认。

        返回服务端 JSON 响应（含 ``id``、``object``、``filename``、``bytes`` 等字段）。
        """
        file_tuple = _build_file_tuple(file, filename=filename, content_type=content_type)
        return self._post_multipart(
            "/v1/files",
            files={"file": file_tuple},
            data={"purpose": purpose},
            timeout=timeout,
        )

    # ── 对象存储 /v1/storage（媒体素材 / 产物文件）─────────────────────────
    def upload_storage(
        self,
        file: Union[str, "os.PathLike[str]", bytes, bytearray, BinaryIO, Tuple[Any, ...]],
        *,
        filename: Optional[str] = None,
        content_type: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """调用 ``POST /v1/storage`` —— 上传素材文件，底层走 kimifs。

        与 :meth:`upload_file`（透传 OpenGW）不同：本接口返回**公网可访问的签名
        下载 URL**，可直接作为媒体生成工具（``generate_image`` / ``generate_video``
        等）的 ``reference_*_urls`` 传入。

        参数:
            file:         待上传文件，形态同 :meth:`upload_file`（路径 / 字节 /
                          类文件对象 / ``(filename, content[, content_type])`` 元组）。
            filename:     覆盖文件名。
            content_type: 显式 MIME 类型；不传按后缀猜测。
            timeout:      本次请求超时（秒）。

        返回服务端 JSON：``{file_id, file_name, size_bytes, content_type, ext,
        checksum, create_time, signed_url}``。
        """
        file_tuple = _build_file_tuple(file, filename=filename, content_type=content_type)
        return self._post_multipart(
            "/v1/storage",
            files={"file": file_tuple},
            timeout=timeout,
        )

    def get_storage_file(self, file_id: str, *, timeout: Optional[float] = None) -> Any:
        """调用 ``GET /v1/storage/{file_id}`` —— 取文件元信息并重新签发 ``signed_url``。

        返回服务端 JSON（字段同 :meth:`upload_storage`）。``file_id`` 不存在时抛
        :class:`NotFoundError`。
        """
        return self._get_json(f"/v1/storage/{file_id}", timeout=timeout)

    def download_storage(
        self,
        file_id: str,
        *,
        dest: Optional[Union[str, "os.PathLike[str]"]] = None,
        timeout: Optional[float] = None,
    ) -> bytes:
        """下载 ``/v1/storage`` 文件的二进制内容。

        先经 :meth:`get_storage_file` 拿到 ``signed_url``，再直接 ``GET`` 该 URL
        （公网，kimifs 会 307 重定向到对象存储）。agent-gw 不承载文件流量，故下载
        不带 apikey、不经网关。

        参数:
            dest:    可选；给定则把内容写入该路径。
            timeout: 本次请求超时（秒）。

        返回文件内容 ``bytes``（若 ``dest`` 给定则同时落盘）。
        """
        meta = self.get_storage_file(file_id, timeout=timeout)
        signed_url = (meta or {}).get("signed_url") if isinstance(meta, Mapping) else None
        if not signed_url:
            raise APIError("storage file has no signed_url", status_code=0, body=meta)
        try:
            # 直接打 signed_url（公网，不经网关、不带 apikey）。用 session.request
            # 而非 self._request，避免附加 Authorization 等网关头。
            resp = self._session.request(
                "GET",
                signed_url,
                timeout=timeout if timeout is not None else self.timeout,
                allow_redirects=True,
            )
        except requests.exceptions.RequestException as e:
            raise TransportError(f"download error for {file_id}: {e}") from e
        if resp.status_code >= 400:
            raise APIError(
                f"download failed: HTTP {resp.status_code}",
                status_code=resp.status_code,
                body=resp.text,
            )
        content = resp.content
        if dest is not None:
            Path(os.fspath(dest)).write_bytes(content)
        return content

    # ── server-sent events (chat/completions, messages) ───────────────────
    def _sse_iter(
        self,
        path: str,
        body: Mapping[str, Any],
        *,
        timeout: Optional[float] = None,
    ) -> Iterator[Dict[str, Any]]:
        headers = {"Accept": "text/event-stream"}
        resp = self._request(
            "POST", path, json=body, headers=headers, timeout=timeout, stream=True
        )
        try:
            for raw in resp.iter_lines(decode_unicode=True):
                if not raw:
                    continue
                if raw.startswith(":"):  # SSE comment
                    continue
                if raw.startswith("data:"):
                    data = raw[5:].lstrip()
                    if data == "[DONE]":
                        return
                    try:
                        yield _json.loads(data)
                    except ValueError:
                        yield {"_raw": data}
        finally:
            resp.close()


def _build_file_tuple(
    file: Any,
    *,
    filename: Optional[str],
    content_type: Optional[str],
) -> Tuple[str, bytes, str]:
    """把多种文件入参形态统一成 ``(filename, content_bytes, content_type)`` 三元组，
    供 requests ``files={"file": ...}`` 使用。"""
    # 已经是 requests 接受的 tuple：原样透传（不再二次推断）
    if isinstance(file, tuple):
        return file  # type: ignore[return-value]

    def _ct(name: str) -> str:
        return content_type or mimetypes.guess_type(name)[0] or "application/octet-stream"

    # 路径
    if isinstance(file, (str, os.PathLike)):
        path = Path(os.fspath(file))
        name = filename or path.name
        return (name, path.read_bytes(), _ct(name))

    # 原始字节
    if isinstance(file, (bytes, bytearray)):
        name = filename or "upload"
        return (name, bytes(file), _ct(name))

    # 类文件对象
    if hasattr(file, "read"):
        raw_name = filename or getattr(file, "name", None) or "upload"
        name = os.path.basename(str(raw_name))
        content = file.read()
        if isinstance(content, str):
            content = content.encode()
        return (name, content, _ct(name))

    raise TypeError(f"unsupported file type for upload: {type(file).__name__}")


def _extract_error_message(body: Any) -> Optional[str]:
    if not isinstance(body, Mapping):
        return None
    err = body.get("error")
    if isinstance(err, Mapping):
        msg = err.get("message")
        if isinstance(msg, str) and msg:
            return msg
    if isinstance(err, str) and err:
        return err
    msg = body.get("message")
    if isinstance(msg, str) and msg:
        return msg
    return None


def _extract_error_code(body: Any) -> Optional[str]:
    """从错误响应体提取结构化 code（如 api_key_path_forbidden）。"""
    if not isinstance(body, Mapping):
        return None
    err = body.get("error")
    if isinstance(err, Mapping):
        code = err.get("code")
        if isinstance(code, str) and code:
            return code
    return None
